/**
 * The Strudel voice instrument's DSP: an AudioWorklet processor that runs inside Strudel's audio
 * graph. The compiled Strudel program carries this function's source text, loads it with
 * `audioWorklet.addModule` and registers it as a Strudel sound, so the voice is generated by Strudel
 * itself and its output runs through Strudel's normal effects chain.
 *
 * Nothing here may refer to anything outside the function: it is serialised with toString() and
 * evaluated in the AudioWorkletGlobalScope (or under a Node harness in tests and scripts). Worklet
 * globals (sampleRate, currentFrame, AudioWorkletProcessor, registerProcessor) are read from
 * globalThis. No class fields (bundlers may lower them into outside helpers).
 *
 * One processor instance speaks one utterance, as one continuous sound: the glottal source keeps
 * its phase and the filters keep their state from the first sample to the last. Parameters arrive
 * as a control track (see track.ts) and are interpolated per sample, so articulation changes
 * without any event boundary.
 *
 * Source: Fant's LF glottal flow derivative shaped by Rd, with jitter, shimmer, flutter, breath
 * noise gated by the open phase, and spectral tilt. Tract: Klatt's cascade (nasal pole/zero pair,
 * five formants and fixed higher poles) plus the parallel frication branch with a bypass path.
 */
export function voiceProcessorModule(name: string): void {
  const g = globalThis as unknown as {
    sampleRate: number
    currentFrame: number
    AudioWorkletProcessor: new () => { port: MessagePort }
    registerProcessor: (n: string, c: unknown) => void
  }
  const SR = g.sampleRate
  const TWO_PI = 2 * Math.PI
  const NOSET = (() => {}) as (...args: number[]) => void
  const ID = (x: number) => x
  /** track parameters, in the order the encoder writes them, and their integer scale */
  const KEYS = ['f0', 'av', 'ah', 'af', 'bp', 'rd', 'f1', 'f2', 'f3', 'f4', 'f5', 'b1', 'b2', 'b3', 'b4', 'b5', 'nz', 'p1', 'w1', 'g1', 'p2', 'w2', 'g2', 'p3', 'w3', 'g3', 'hp', 'cl', 'ns']
  const SCALE: Record<string, number> = { f0: 10, av: 1000, ah: 1000, af: 1000, bp: 1000, rd: 100, g1: 1000, g2: 1000, g3: 1000, cl: 1000 }
  /** decode a track string: per parameter, breakpoints "v" or "d:v" (d frames on), linear between */
  function decodeTrack(text: string): { frames: number; track: Record<string, Float32Array>; bursts: number[][] } {
    // stop releases after '#': "time gain tau;..." (seconds, linear, ms)
    const [main, ev] = text.split('#')
    const bursts = ev ? ev.split(';').filter(Boolean).map((b) => b.split(' ').map(Number)) : []
    const parts = main!.split('|')
    const pts = parts.map((p) => {
      let at = 0
      return p.split(' ').map((tok, i) => {
        const c = tok.indexOf(':')
        if (i > 0) at += c >= 0 ? Number(tok.slice(0, c)) : 1
        return [at, Number(c >= 0 ? tok.slice(c + 1) : tok)] as const
      })
    })
    const frames = Math.max(...pts.map((p) => p[p.length - 1]![0])) + 1
    const track: Record<string, Float32Array> = {}
    KEYS.forEach((k, j) => {
      const a = new Float32Array(frames)
      const p = pts[j] ?? [[0, 0] as const]
      const sc = SCALE[k] ?? 1
      for (let m = 0; m < p.length; m++) {
        const [t0, v0] = p[m]!
        const [t1, v1] = p[m + 1] ?? [frames - 1, v0]
        for (let t = t0; t <= t1; t++) a[t] = (v0 + ((v1 - v0) * (t - t0)) / Math.max(1, t1 - t0)) / sc
        if (!p[m + 1]) for (let t = t0; t < frames; t++) a[t] = v0 / sc
      }
      track[k] = a
    })
    return { frames, track, bursts }
  }

  /** two-pole resonator, y = a x + b y1 + c y2 (Klatt 1980); unity gain at DC, or at the peak */
  function resonator(peak: boolean) {
    const r = { a: 1, b: 0, c: 0, y1: 0, y2: 0, set: NOSET, step: ID }
    r.set = (f, bw) => {
      const fr = Math.min(f, SR * 0.49)
      const e = Math.exp((-Math.PI * bw) / SR)
      r.c = -e * e
      r.b = 2 * e * Math.cos((TWO_PI * fr) / SR)
      r.a = 1 - r.b - r.c
      if (peak) {
        const w = (TWO_PI * fr) / SR
        r.a = Math.hypot(1 - r.b * Math.cos(w) - r.c * Math.cos(2 * w), r.b * Math.sin(w) + r.c * Math.sin(2 * w))
      }
    }
    r.step = (x) => {
      const y = r.a * x + r.b * r.y1 + r.c * r.y2
      r.y2 = r.y1
      r.y1 = y
      return y
    }
    return r
  }
  /** anti-resonator, the inverse of a resonator (nasal zero) */
  function antiResonator() {
    const r = { a: 1, b: 0, c: 0, x1: 0, x2: 0, set: NOSET, step: ID }
    r.set = (f, bw) => {
      const e = Math.exp((-Math.PI * bw) / SR)
      const c = -e * e
      const b = 2 * e * Math.cos((TWO_PI * Math.min(f, SR * 0.49)) / SR)
      const a = 1 - b - c
      r.a = 1 / a
      r.b = -b / a
      r.c = -c / a
    }
    r.step = (x) => {
      const y = r.a * x + r.b * r.x1 + r.c * r.x2
      r.x2 = r.x1
      r.x1 = x
      return y
    }
    return r
  }
  /** RBJ biquad high-pass */
  function highPass(q: number) {
    const h = { b0: 1, b1: 0, b2: 0, a1: 0, a2: 0, x1: 0, x2: 0, y1: 0, y2: 0, set: NOSET as (fc: number) => void, step: ID }
    h.set = (fc) => {
      if (fc <= 0) {
        h.b0 = 1
        h.b1 = h.b2 = h.a1 = h.a2 = 0
        return
      }
      const w = (TWO_PI * Math.min(fc, SR * 0.45)) / SR
      const al = Math.sin(w) / (2 * q)
      const cw = Math.cos(w)
      const a0 = 1 + al
      h.b0 = (1 + cw) / 2 / a0
      h.b1 = -(1 + cw) / a0
      h.b2 = h.b0
      h.a1 = (-2 * cw) / a0
      h.a2 = (1 - al) / a0
    }
    h.step = (x) => {
      const y = h.b0 * x + h.b1 * h.x1 + h.b2 * h.x2 - h.a1 * h.y1 - h.a2 * h.y2
      h.x2 = h.x1
      h.x1 = x
      h.y2 = h.y1
      h.y1 = y
      return y
    }
    return h
  }
  /** LF flow derivative (Fant 1995), shape from Rd, negative peak -1 */
  function lfPulse() {
    const p = { alpha: 0, e0: 0, eps: 0, shift: 0, delta: 0, te: 0, omega: 0, setRd: NOSET as (rd: number) => void, at: ID }
    p.setRd = (rdIn) => {
      const rd = Math.min(2.7, Math.max(0.3, rdIn))
      const ra = -0.01 + 0.048 * rd
      const rk = 0.224 + 0.118 * rd
      const rg = ((rk / 4) * (0.5 + 1.2 * rk)) / (0.11 * rd - ra * (0.5 + 1.2 * rk))
      const tp = 1 / (2 * rg)
      const te = tp + tp * rk
      const eps = 1 / ra
      const shift = Math.exp(-eps * (1 - te))
      const delta = 1 - shift
      const rhs = ((1 / eps) * (shift - 1) + (1 - te) * shift) / delta
      const upper = -(rhs - (te - tp) / 2)
      const omega = Math.PI / tp
      const s = Math.sin(omega * te)
      const alpha = Math.log((-Math.PI * s * upper) / (tp * 2)) / (tp / 2 - te)
      p.e0 = -1 / (s * Math.exp(alpha * te))
      p.alpha = alpha
      p.eps = eps
      p.shift = shift
      p.delta = delta
      p.te = te
      p.omega = omega
    }
    p.at = (t) => (t > p.te ? (-Math.exp(-p.eps * (t - p.te)) + p.shift) / p.delta : p.e0 * Math.exp(p.alpha * t) * Math.sin(p.omega * t))
    return p
  }

  interface Options {
    /** start time in samples (AudioContext frame) */
    start: number
    /** control track, encoded (see decodeTrack) */
    track: string
    frameSeconds: number
    rd: number
    jitter: number
    shimmer: number
    breath: number
    tilt: number
    flutter: number
    gain: number
    /** formant scale for the fixed poles above F5 */
    scale: number
    seed: number
    /** depth of the glottal modulation of frication in voiced obstruents (0: Klatt's fixed 50%) */
    vmod?: number
    /** corner of the constricted-tract low-pass for voicing during obstruents, Hz */
    clHz?: number
    /** level of the low-passed voicing relative to the unfiltered (makes up the lost bandwidth) */
    clGain?: number
    /** recorded consonant noise (16 kHz mu-law, base64), indexed by the track's ns - 1 */
    snd?: string[]
    /** levels of recorded frication (× af) and releases (× burst gain) */
    recGain?: number
    recBurst?: number
    sndGain?: number[]
  }

  const Base = g.AudioWorkletProcessor
  class Voice extends Base {
    o: Options
    tr: Record<string, Float32Array>
    frames: number
    s: Record<string, number>
    r: ReturnType<typeof resonator>[]
    q: ReturnType<typeof resonator>[]
    hi: ReturnType<typeof resonator>[]
    np: ReturnType<typeof resonator>
    nz: ReturnType<typeof antiResonator>
    hp: ReturnType<typeof highPass>[]
    lf: ReturnType<typeof lfPulse>
    bursts: number[][]
    snd: Float32Array[]
    done: boolean
    n: number
    constructor(init: { processorOptions: Options }) {
      super()
      const o = init.processorOptions
      this.o = o
      const t = decodeTrack(o.track)
      this.tr = t.track
      this.frames = t.frames
      this.bursts = t.bursts
      // recorded noise: mu-law bytes to float
      this.snd = (o.snd ?? []).map((b64) => {
        // base64 by hand: AudioWorkletGlobalScope has no atob
        const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
        const s64 = b64.replace(/=+$/, '')
        const bytes: number[] = []
        for (let j = 0, acc = 0, bits = 0; j < s64.length; j++) {
          acc = (acc << 6) | A.indexOf(s64[j]!)
          bits += 6
          if (bits >= 8) {
            bits -= 8
            bytes.push((acc >> bits) & 255)
          }
        }
        const a = new Float32Array(bytes.length)
        for (let j = 0; j < bytes.length; j++) {
          const y = bytes[j]! / 127.5 - 1
          a[j] = (Math.sign(y) * (Math.pow(256, Math.abs(y)) - 1)) / 255
        }
        return a
      })
      this.n = 0
      this.done = false
      this.r = [0, 1, 2, 3, 4].map(() => resonator(false))
      this.q = [0, 1, 2].map(() => resonator(true))
      this.hi = [5600, 6700, 7800, 8900]
        .map((f) => f * o.scale)
        .filter((f) => f < SR * 0.45)
        .map((f, i) => {
          const r = resonator(false)
          r.set(f, 500 + 250 * i)
          return r
        })
      this.np = resonator(false)
      this.nz = antiResonator()
      this.hp = [highPass(0.54), highPass(1.31)]
      this.lf = lfPulse()
      this.lf.setRd(o.rd)
      // running state: glottal phase, period, jitter/shimmer, filters, noise
      this.s = { phase: 1, period: SR / 120, amp: 1, tilt: 0, prev: 0, lp: 0, rng: o.seed >>> 0 || 1, hpFc: -1, bi: 0, bEnv: 0, bDecay: 1, bAtt: 0, bGain: 0, l1: 0, l2: 0, rp: 0, rd: 1, bs: -1, bp: 0 }
    }
    noise(): number {
      // xorshift32, four uniforms summed: roughly Gaussian, unit variance
      let x = this.s.rng!
      let sum = 0
      for (let i = 0; i < 4; i++) {
        x ^= x << 13
        x ^= x >>> 17
        x ^= x << 5
        sum += (x >>> 0) / 4294967296
      }
      this.s.rng = x
      return (sum - 2) * 1.732
    }
    process(_in: Float32Array[][], out: Float32Array[][]): boolean {
      const o = this.o
      const ch = out[0]![0]!
      const tr = this.tr
      const frames = this.frames
      const per = o.frameSeconds * SR
      const end = Math.ceil(frames * per)
      const s = this.s
      const first = g.currentFrame
      const f = (k: string, i: number, u: number) => {
        const a = tr[k]!
        return a[i]! + (a[Math.min(frames - 1, i + 1)]! - a[i]!) * u
      }
      let av = 0
      let ah = 0
      let af = 0
      let bp = 0
      let g1 = 0
      let g2 = 0
      let g3 = 0
      let cl = 0
      let ns = 0
      const step = 16000 / SR
      const lpA = Math.exp((-TWO_PI * (o.clHz ?? 400)) / SR)
      for (let k = 0; k < ch.length; k++) {
        const n = first + k - o.start
        if (n < 0) {
          ch[k] = 0
          continue
        }
        if (n >= end) {
          ch[k] = 0
          this.done = true
          continue
        }
        const fp = n / per
        const i = Math.min(frames - 1, Math.floor(fp))
        const u = fp - i
        // filter coefficients every 16 samples (0.3 ms): smooth glides, no frame steps
        if ((n & 15) === 0) {
          for (let j = 0; j < 5; j++) this.r[j]!.set(f('f' + (j + 1), i, u), f('b' + (j + 1), i, u))
          this.np.set(270 * o.scale, 100)
          this.nz.set(f('nz', i, u), 100)
          for (let j = 0; j < 3; j++) this.q[j]!.set(f('p' + (j + 1), i, u), f('w' + (j + 1), i, u))
          const fc = tr.hp![i]!
          if (fc !== s.hpFc) {
            s.hpFc = fc
            this.hp[0]!.set(fc)
            this.hp[1]!.set(fc)
          }
          av = f('av', i, u)
          ah = f('ah', i, u)
          af = f('af', i, u)
          bp = f('bp', i, u)
          g1 = f('g1', i, u)
          g2 = f('g2', i, u)
          g3 = f('g3', i, u)
          cl = f('cl', i, u)
          ns = Math.round(tr.ns![i]!)
        }
        // --- stop release: a transient at the exact release sample, then burst noise decaying
        // with a place-dependent time constant (Stevens 1998, ch. 7), into the parallel branch
        let impulse = 0
        const b = this.bursts[s.bi!]
        if (b && n >= Math.round(b[0]! * SR)) {
          s.bi! += 1
          s.bGain = b[1]!
          s.bEnv = 1
          s.bAtt = 0
          s.bDecay = Math.exp(-1 / ((b[2]! / 1000) * SR))
          impulse = b[1]! * 6
          // a recorded release replaces the synthetic transient and noise
          if (b[3] && this.snd[b[3] - 1]) {
            s.bs = b[3] - 1
            s.bp = 0
            s.bEnv = 0
            impulse = 0
          }
        }
        // --- glottal source: one LF pulse per period; length and shape fixed at the period start
        if (s.phase! >= 1) {
          s.phase! -= 1
          const t = n / SR
          const fl = 1 + (0.015 * o.flutter * (Math.sin(TWO_PI * 12.7 * t) + Math.sin(TWO_PI * 7.1 * t) + Math.sin(TWO_PI * 4.7 * t))) / 3
          const f0 = Math.max(40, f('f0', i, u) * fl)
          s.period = (SR / f0) * (1 + o.jitter * this.noise())
          s.amp = 1 + o.shimmer * this.noise()
          this.lf.setRd(f('rd', i, u) || o.rd)
        }
        const d = this.lf.at(s.phase!)
        const open = s.phase! < this.lf.te
        s.phase! += 1 / s.period!
        // first-order emphasis for the missing poles above F5, then optional tilt
        const emph = d - 0.6 * s.prev!
        s.prev = d
        s.tilt = (1 - o.tilt) * emph + o.tilt * s.tilt!
        const voicing = s.tilt * av * s.amp! * 0.026
        const w = this.noise()
        s.lp = 0.5 * w + 0.5 * s.lp!
        const asp = s.lp * (ah + o.breath * av * (open ? 1 : 0.35)) * 0.004
        // --- cascade
        let x = this.nz.step(this.np.step(voicing + asp))
        for (let j = 0; j < this.hi.length; j++) x = this.hi[j]!.step(x)
        for (let j = 4; j >= 0; j--) x = this.r[j]!.step(x)
        // constricted tract: with the mouth closed or narrowed, voicing is radiated mainly at low
        // frequencies (the voice bar; Stevens 1998, ch. 7-8), so the cascade output is low-passed
        if (cl > 0.001) {
          s.l1 = (1 - lpA) * x + lpA * s.l1!
          s.l2 = (1 - lpA) * s.l1! + lpA * s.l2!
          x = x * (1 - cl) + s.l2! * cl * (o.clGain ?? 2)
        }
        // --- parallel frication, modulated by the glottal cycle when voiced (Klatt 1980): the
        // turbulence follows the airflow, so it pulses at f0 in voiced fricatives
        const vm = o.vmod ?? 0
        const mod = av > 0.05 ? (vm > 0 ? 1 - Math.min(vm, 3 * av) * (open ? 0 : 1) : 1 - Math.min(0.5, av) * (open ? 0 : 1)) : 1
        let burst = 0
        if (s.bEnv! > 1e-4) {
          s.bAtt = Math.min(1, s.bAtt! + 1 / (0.0004 * SR))
          burst = s.bGain! * s.bEnv! * s.bAtt!
          s.bEnv! *= s.bDecay!
        }
        const fr = this.hp[1]!.step(this.hp[0]!.step(this.noise() * (ns > 0 ? 0 : af * mod + burst) + impulse)) * 0.0055
        let p = this.q[0]!.step(fr) * g1 + this.q[1]!.step(fr) * g2 + this.q[2]!.step(fr) * g3 + fr * bp
        // recorded turbulence, read back and forth through its snippet (no loop seam), shaped by af
        const rec = ns > 0 ? this.snd[ns - 1] : undefined
        if (rec) {
          const j = Math.floor(s.rp!)
          const v = rec[j]! + (rec[Math.min(rec.length - 1, j + 1)]! - rec[j]!) * (s.rp! - j)
          s.rp! += step * s.rd!
          if (s.rp! >= rec.length - 2) s.rd = -1
          if (s.rp! <= 0) s.rd = 1
          p += v * af * mod * (o.recGain ?? 0.02) * (o.sndGain?.[ns - 1] ?? 1)
        }
        // recorded release, one shot
        if (s.bs! >= 0) {
          const r = this.snd[s.bs!]!
          const j = Math.floor(s.bp!)
          if (j < r.length - 1) {
            p += (r[j]! + (r[j + 1]! - r[j]!) * (s.bp! - j)) * s.bGain! * (o.recBurst ?? 0.02) * (o.sndGain?.[s.bs!] ?? 1)
            s.bp! += step
          } else s.bs = -1
        }
        ch[k] = (x + p) * o.gain
      }
      if (this.done) this.port.postMessage('done')
      return !this.done
    }
  }
  g.registerProcessor(name, Voice)
}
